def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Uniform nonzero rows/columns are the grid's dividers.
    div_rows = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    div_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def compartments(size, divs):
        bounds = [-1] + divs + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    rows = compartments(h, div_rows)
    cols = compartments(w, div_cols)

    def cells_with_color(box, color):
        r0, r1, c0, c1 = box
        return [(r, c) for r in range(r0, r1) for c in range(c0, c1)
                if grid[r][c] == color]

    def reflect(source, target, color, axis):
        sr0, sr1, sc0, sc1 = source
        tr0, tr1, tc0, tc1 = target
        if axis == "horizontal":
            for r, c in cells_with_color(source, color):
                rr = tr0 + (r - sr0)
                cc = tc1 - 1 - (c - sc0)
                if tr0 <= rr < tr1 and tc0 <= cc < tc1:
                    out[rr][cc] = color
        else:
            for r, c in cells_with_color(source, color):
                rr = tr1 - 1 - (r - sr0)
                cc = tc0 + (c - sc0)
                if tr0 <= rr < tr1 and tc0 <= cc < tc1:
                    out[rr][cc] = color

    for color in range(1, 10):
        # Find each 2-by-2 compartment block with exactly one missing copy.
        for ri in range(len(rows) - 1):
            for ci in range(len(cols) - 1):
                boxes = []
                for rseg in (rows[ri], rows[ri + 1]):
                    for cseg in (cols[ci], cols[ci + 1]):
                        boxes.append((rseg[0], rseg[1], cseg[0], cseg[1]))
                occupied = [bool(cells_with_color(box, color)) for box in boxes]
                if sum(occupied) != 3:
                    continue
                missing = occupied.index(False)
                mr, mc = divmod(missing, 2)
                target = boxes[missing]

                # Prefer reflecting from the occupied compartment in the same row.
                same_row = boxes[mr * 2 + (1 - mc)]
                if cells_with_color(same_row, color):
                    reflect(same_row, target, color, "horizontal")
                else:
                    same_col = boxes[(1 - mr) * 2 + mc]
                    if cells_with_color(same_col, color):
                        reflect(same_col, target, color, "vertical")

    return out
